namespace App.Common;

/// <summary>A field of an update: absent (it keeps its value), or present with a value, which may be null.</summary>
public sealed class Patch<T>
{
    private Patch(bool isPresent, T? value)
    {
        IsPresent = isPresent;
        Value = value;
    }

    /// <summary>The field keeps its value.</summary>
    public static Patch<T> Absent { get; } = new(false, default);

    /// <summary>The field takes this value, which may be null.</summary>
    public static Patch<T> Of(T? value) => new(true, value);

    public bool IsPresent { get; }

    /// <summary>The value to set; default when absent.</summary>
    public T? Value { get; }

    public override string ToString() => IsPresent ? $"Patch[{Value}]" : "Patch.Absent";
}

using App.ApplicationModels;
using App.Entities;
using Customer = App.Entities.Customer;
using CustomerModel = App.ApplicationModels.Customer;

namespace App.Conversions;

/// <summary>Conversions between the application models and the "customers" table: what the service takes and returns.</summary>
public static class CustomerConversions
{
    /// <summary>A Location as the documents of the customers collection keep it.</summary>
    private static Customer.AddressDocument.LocationDocument CustomerAddressLocationToDocument(Location value)
    {
        return new Customer.AddressDocument.LocationDocument
        {
            Latitude = value.Latitude,
            Longitude = value.Longitude,
        };
    }

    /// <summary>An Address as the documents of the customers collection keep it.</summary>
    private static Customer.AddressDocument CustomerAddressToDocument(Address value)
    {
        return new Customer.AddressDocument
        {
            Street = value.Street,
            ZipCode = value.ZipCode,
            Location = value.Location is null ? null : CustomerAddressLocationToDocument(value.Location),
        };
    }

    /// <summary>A Customer as the customers table takes it.</summary>
    public static Customer CustomerModelToCustomer(CustomerModel model)
    {
        return new Customer
        {
            Email = model.Email,
            Since = model.Since.UtcDateTime,
            Address = CustomerAddressToDocument(model.Address),
            Tags = model.Tags,
        };
    }

    /// <summary>A document of the customers collection as a Location.</summary>
    private static Location CustomerAddressLocationFromDocument(Customer.AddressDocument.LocationDocument value)
    {
        return new Location(
            value.Latitude,
            value.Longitude
        );
    }

    /// <summary>A document of the customers collection as an Address.</summary>
    private static Address CustomerAddressFromDocument(Customer.AddressDocument value)
    {
        return new Address(
            value.Street,
            value.ZipCode,
            value.Location is null ? null : CustomerAddressLocationFromDocument(value.Location)
        );
    }

    /// <summary>A row of the customers table as a Customer.</summary>
    public static CustomerModel CustomerToCustomerModel(Customer row)
    {
        return new CustomerModel(
            row.Id,
            row.Email,
            new DateTimeOffset(DateTime.SpecifyKind(row.Since, DateTimeKind.Utc)),
            CustomerAddressFromDocument(row.Address),
            row.Tags!
        );
    }
}

