using App.ApplicationModels;
using App.Entities;
using Order = App.Entities.Order;
using OrderModel = App.ApplicationModels.Order;

namespace App.Conversions;

/// <summary>Conversions between the application models and the "orders" table: what the service takes and returns.</summary>
public static class OrderConversions
{
    /// <summary>A Discount as the documents of the orders collection keep it.</summary>
    private static Order.LineDocument.DiscountDocument OrderLinesDiscountsToDocument(Discount value)
    {
        return new Order.LineDocument.DiscountDocument
        {
            Reason = value.Reason,
            Percent = value.Percent,
        };
    }

    /// <summary>An OrderLine as the documents of the orders collection keep it.</summary>
    private static Order.LineDocument OrderLinesToDocument(OrderLine value)
    {
        return new Order.LineDocument
        {
            Id = value.Id,
            Sku = value.Sku,
            Quantity = value.Quantity,
            Price = value.Price,
            Status = value.Status,
            Discounts = value.Discounts.Select(OrderLinesDiscountsToDocument).ToList(),
        };
    }

    /// <summary>A Shipping as the documents of the orders collection keep it.</summary>
    private static Order.ShippingDocument OrderShippingToDocument(Shipping value)
    {
        return new Order.ShippingDocument
        {
            Carrier = value.Carrier,
            SentOn = value.SentOn.ToDateTime(TimeOnly.MinValue, DateTimeKind.Utc),
        };
    }

    /// <summary>An Order as the orders table takes it.</summary>
    public static Order OrderModelToOrder(OrderModel model)
    {
        return new Order
        {
            Code = model.Code,
            Lines = model.Lines.Select(OrderLinesToDocument).ToList(),
            Shipping = model.Shipping is null ? null : OrderShippingToDocument(model.Shipping),
        };
    }

    /// <summary>A document of the orders collection as a Discount.</summary>
    private static Discount OrderLinesDiscountsFromDocument(Order.LineDocument.DiscountDocument value)
    {
        return new Discount
        {
            Reason = value.Reason,
            Percent = value.Percent,
        };
    }

    /// <summary>A document of the orders collection as an OrderLine.</summary>
    private static OrderLine OrderLinesFromDocument(Order.LineDocument value)
    {
        return new OrderLine
        {
            Id = value.Id,
            Sku = value.Sku,
            Quantity = value.Quantity,
            Price = value.Price,
            Status = value.Status,
            Discounts = value.Discounts?.Select(OrderLinesDiscountsFromDocument).ToArray() ?? [],
        };
    }

    /// <summary>A document of the orders collection as a Shipping.</summary>
    private static Shipping OrderShippingFromDocument(Order.ShippingDocument value)
    {
        return new Shipping(
            value.Carrier,
            DateOnly.FromDateTime(value.SentOn)
        );
    }

    /// <summary>A row of the orders table as an Order.</summary>
    public static OrderModel OrderToOrderModel(Order row)
    {
        return new OrderModel(
            row.Id,
            row.Code,
            row.Lines.Select(OrderLinesFromDocument).ToList(),
            row.Shipping is null ? null : OrderShippingFromDocument(row.Shipping)
        );
    }
}

