        // Not stored: Fragile
        // TODO: Contents: no field of the model gives it (contents)
        // TODO: Size: DB2CRUD does not write this conversion (Size)
        return new Shipment.ParcelDocument
        {
            Weight = value.Weight,
        };
    }

