    public static Shipment ShipmentModelToShipment(ShipmentModel model)
    {
        return new Shipment
        {
            Parcel = ShipmentParcelToDocument(model.Parcel),
            Stops = default!, // TODO: Stops: DB2CRUD does not write this conversion (Stops)
        };
    }

    /// <summary>A document of the shipments collection as a Parcel.</summary>
    private static Parcel ShipmentParcelFromDocument(Shipment.ParcelDocument value)
    {
        return new Parcel(
            value.Weight,
            default!, // TODO: Size: DB2CRUD does not write this conversion (Size)
            default! // TODO: Fragile: no field of the model gives it (Fragile)
        );
    }

    /// <summary>A row of the shipments table as a Shipment.</summary>
    public static ShipmentModel ShipmentToShipmentModel(Shipment row)
    {
        return new ShipmentModel(
            row.Id,
            ShipmentParcelFromDocument(row.Parcel),
            default! // TODO: Stops: DB2CRUD does not write this conversion (Stops)
        );
