using App.Common;
using App.Entities;

namespace App.Repositories;

/// <summary>Keeps shipments rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryShipmentRepository : IShipmentRepository
{
    private readonly Dictionary<string, Shipment> rows = [];

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(Shipment row) => [row.Id];

    private static string KeyText(Shipment row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<Shipment> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<Shipment?> FindByIdAsync(string id)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Id, id)));
    }

    public Task<Page<Shipment>> ListAsync(int offset, int limit)
    {
        var rows = Visible().ToList();
        return Task.FromResult(new Page<Shipment>(rows.Skip(offset).Take(limit).ToList(), rows.Count, offset, limit));
    }

    public Task<Shipment> InsertAsync(Shipment entity)
    {
        entity.Id ??= MongoDB.Bson.ObjectId.GenerateNewId().ToString();
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<Shipment> UpdateAsync(Shipment entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(Shipment entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }

    public Task<Shipment?> AddStopAsync(string id, Shipment.StopDocument stop)
    {
        var found = Visible().FirstOrDefault(row => Equals(row.Id, id));
        if (found is null) return Task.FromResult<Shipment?>(null);
        found.Stops = [..found.Stops ?? [], stop];
        return Task.FromResult<Shipment?>(found);
    }

    public Task<Shipment?> RemoveStopAsync(string id, int position, int size)
    {
        var found = Visible().FirstOrDefault(row => Equals(row.Id, id));
        if (found is null || (found.Stops?.Count ?? 0) != size) return Task.FromResult<Shipment?>(null);
        found.Stops = (found.Stops ?? []).Where((_, index) => index != position).ToList();
        return Task.FromResult<Shipment?>(found);
    }
}

