using System.Globalization;
using App;
using App.Common;
using App.Entities;
using App.Errors;

namespace App.Services;

/// <summary>Operations on customers. Repositories commit every write.</summary>
public class CustomerService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "customers" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Customer? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Email");
            if (value is null)
                if (creating || values.ContainsKey("Email")) errors.Add(new FieldError("email", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Level");
            if (value is not null)
            {
                if (!new[] { "basic", "gold" }.Contains(Convert.ToString(value, CultureInfo.InvariantCulture))) errors.Add(new FieldError("level", "must be one of: basic, gold"));
            }
        }
        {
            var value = values.GetValueOrDefault("Since");
            if (value is null)
                if (creating || values.ContainsKey("Since")) errors.Add(new FieldError("since", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Address");
            if (value is null)
            {
                if (creating || values.ContainsKey("Address")) errors.Add(new FieldError("address", "is required"));
            }
            else
            {
                var document = (Customer.AddressDocument)value;
                if (document is not null) CheckAddress(document, "address", errors);
            }
        }
        if (errors.Count > 0) throw new ValidationFailedException("Customer", errors);
    }

    /// <summary>Values that must be unique are not taken by another row.</summary>
    private static async Task CheckUniqueAsync(IUnitOfWork uow, Dictionary<string, object?> values, Customer? current)
    {
        {
            var email = values.TryGetValue("Email", out var givenEmail) ? (string?)givenEmail : current?.Email;
            if (email is not null)
            {
                var other = await uow.Customers.FindByEmailAsync(email);
                if (other is not null && (current is null || !Equals(other.Id, current.Id)))
                    throw new ConflictException("Customer", "email is already taken", ["Email"]);
            }
        }
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Customer? current)
    {
        await ValidateAsync(uow, values, current);
        await CheckUniqueAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Customer entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Email", out var email)) entity.Email = (string)email!;
        if (values.TryGetValue("Level", out var level)) entity.Level = (string?)level;
        if (values.TryGetValue("Since", out var since)) entity.Since = (DateTime)since!;
        if (values.TryGetValue("Address", out var address)) entity.Address = (Customer.AddressDocument)address!;
        if (values.TryGetValue("Tags", out var tags)) entity.Tags = (List<string>?)tags;
    }

    /// <summary>The Customer with this key; NotFoundException when there is none.</summary>
    private static async Task<Customer> FindAsync(IUnitOfWork uow, string id) =>
        await uow.Customers.FindByIdAsync(id) ?? throw new NotFoundException("Customer", id);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(CustomerChanges changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.Email is { IsPresent: true } email) values["Email"] = email.Value;
        if (changes.Level is { IsPresent: true } level) values["Level"] = level.Value;
        if (changes.Since is { IsPresent: true } since) values["Since"] = since.Value;
        if (changes.Address is { IsPresent: true } address) values["Address"] = address.Value;
        if (changes.Tags is { IsPresent: true } tags) values["Tags"] = tags.Value;
        return values;
    }

    /// <summary>What a Customer.AddressDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckAddress(Customer.AddressDocument value, string path, List<FieldError> errors)
    {
        if (value.Street is null) errors.Add(new FieldError(path + ".street", "is required"));
        if (value.ZipCode is null) errors.Add(new FieldError(path + ".zip code", "is required"));
        if (value.Location is not null) CheckAddressLocation(value.Location, path + ".location", errors);
    }

    /// <summary>What a Customer.AddressDocument.LocationDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckAddressLocation(Customer.AddressDocument.LocationDocument value, string path, List<FieldError> errors)
    {
    }

    /// <summary>Stores a new Customer after checking it.</summary>
    public async Task<Customer> CreateCustomerAsync(Customer customer)
    {
        var values = new Dictionary<string, object?>();
        if (customer.Email is not null) values["Email"] = customer.Email;
        if (customer.Level is not null) values["Level"] = customer.Level;
        values["Since"] = customer.Since;
        if (customer.Address is not null) values["Address"] = customer.Address;
        if (customer.Tags is not null) values["Tags"] = customer.Tags;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            return await uow.Customers.InsertAsync(customer);
        });
    }

    /// <summary>The Customer with this key; NotFoundException when there is none.</summary>
    public async Task<Customer> GetCustomerAsync(string id) => await FindAsync(uow, id);

    /// <summary>A page of customers, by primary key.</summary>
    public async Task<Page<Customer>> ListCustomersAsync(int offset, int limit) => await uow.Customers.ListAsync(offset, limit);

    /// <summary>Changes the given values of a Customer.</summary>
    public async Task<Customer> UpdateCustomerAsync(string id, CustomerChanges changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return await uow.Customers.UpdateAsync(current);
        });
    }

    /// <summary>Deletes a Customer.</summary>
    public async Task DeleteCustomerAsync(string id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await uow.Customers.DeleteAsync(current);
        });
    }

    /// <summary>The Customer with this email, or null.</summary>
    public async Task<Customer?> FindCustomerByEmailAsync(string email) => await uow.Customers.FindByEmailAsync(email);

    /// <summary>Adds an item to tags.</summary>
    public async Task<Customer> AddTagAsync(string id, string tag)
    {
        return await this.uow.TransactionAsync(async uow =>
        {
            await FindAsync(uow, id);
            return await uow.Customers.AddTagAsync(id, tag) ?? throw new NotFoundException("Customer", id);
        });
    }

    /// <summary>Removes an item from tags, by its value.</summary>
    public async Task<Customer> RemoveTagAsync(string id, string tag)
    {
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if (current.Tags is null || !current.Tags.Contains(tag)) throw new NotFoundException("Tag", tag);
            return await uow.Customers.RemoveTagAsync(id, tag) ?? throw new NotFoundException("Customer", id);
        });
    }
}

