        var values = new Dictionary<string, object?>();
        if (changes.Code is { IsPresent: true } code) values["Code"] = code.Value;
        if (changes.Lines is { IsPresent: true } lines) values["Lines"] = lines.Value;
        if (changes.Shipping is { IsPresent: true } shipping) values["Shipping"] = shipping.Value;
        return values;
    }

    /// <summary>What a Order.LineDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckLine(Order.LineDocument value, string path, List<FieldError> errors)
    {
        if (value.Sku is null) errors.Add(new FieldError(path + ".sku", "is required"));
        if (value.Status is not null && !new[] { "pending", "sent" }.Contains(value.Status)) errors.Add(new FieldError(path + ".status", "must be one of: pending, sent"));
        if (value.Discounts is not null)
        {
            for (var i0 = 0; i0 < value.Discounts.Count; i0++)
            {
                if (value.Discounts[i0] is null) errors.Add(new FieldError(path + ".discounts" + "." + i0, "is required"));
                else CheckLineDiscount(value.Discounts[i0], path + ".discounts" + "." + i0, errors);
            }
        }
    }

    /// <summary>What a Order.LineDocument.DiscountDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckLineDiscount(Order.LineDocument.DiscountDocument value, string path, List<FieldError> errors)
    {
        if (value.Reason is null) errors.Add(new FieldError(path + ".reason", "is required"));
    }

    /// <summary>What a Order.ShippingDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckShipping(Order.ShippingDocument value, string path, List<FieldError> errors)
    {
        if (value.Carrier is null) errors.Add(new FieldError(path + ".carrier", "is required"));
    }

    /// <summary>Stores a new Order after checking it.</summary>
    public async Task<Order> CreateOrderAsync(Order order)
    {
        var values = new Dictionary<string, object?>();
        if (order.Code is not null) values["Code"] = order.Code;
        if (order.Lines is not null) values["Lines"] = order.Lines;
        if (order.Shipping is not null) values["Shipping"] = order.Shipping;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            return await uow.Orders.InsertAsync(order);
        });
    }

    /// <summary>The Order with this key; NotFoundException when there is none.</summary>
    public async Task<Order> GetOrderAsync(string id) => await FindAsync(uow, id);

    /// <summary>A page of orders, by primary key.</summary>
    public async Task<Page<Order>> ListOrdersAsync(int offset, int limit) => await uow.Orders.ListAsync(offset, limit);

    /// <summary>Changes the given values of a Order.</summary>
    public async Task<Order> UpdateOrderAsync(string id, OrderChanges changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return await uow.Orders.UpdateAsync(current);
        });
    }

    /// <summary>Deletes a Order.</summary>
    public async Task DeleteOrderAsync(string id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await uow.Orders.DeleteAsync(current);
        });
    }

    /// <summary>The Order with this code, or null.</summary>
    public async Task<Order?> FindOrderByCodeAsync(string code) => await uow.Orders.FindByCodeAsync(code);

    /// <summary>Adds an item to lines.</summary>
    public async Task<Order> AddLineAsync(string id, Order.LineDocument line)
    {
        var errors = new List<FieldError>();
        CheckLine(line, "lines", errors);
        if (errors.Count > 0) throw new ValidationFailedException("Order", errors);
        return await this.uow.TransactionAsync(async uow =>
        {
            await FindAsync(uow, id);
            return await uow.Orders.AddLineAsync(id, line) ?? throw new NotFoundException("Order", id);
        });
    }

    /// <summary>Removes an item from lines, by its identifier.</summary>
    public async Task<Order> RemoveLineAsync(string id, string lineId)
    {
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if (current.Lines is null || current.Lines.All(candidate => candidate.Id != lineId)) throw new NotFoundException("Line", lineId);
            return await uow.Orders.RemoveLineAsync(id, lineId) ?? throw new NotFoundException("Order", id);
        });
    }
}

