using App;
using App.Common;
using App.Entities;
using App.Errors;

namespace App.Services;

/// <summary>Operations on shipments. Repositories commit every write.</summary>
public class ShipmentService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "shipments" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Shipment? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Parcel");
            if (value is null)
            {
                if (creating || values.ContainsKey("Parcel")) errors.Add(new FieldError("parcel", "is required"));
            }
            else
            {
                var document = (Shipment.ParcelDocument)value;
                if (document is not null) CheckParcel(document, "parcel", errors);
            }
        }
        {
            var value = values.GetValueOrDefault("Stops");
            if (value is not null)
            {
                var document = (List<Shipment.StopDocument>)value;
                if (document is not null)
                {
                    for (var i0 = 0; i0 < document.Count; i0++)
                    {
                        if (document[i0] is null) errors.Add(new FieldError("stops" + "." + i0, "is required"));
                        else CheckStop(document[i0], "stops" + "." + i0, errors);
                    }
                }
            }
        }
        if (errors.Count > 0) throw new ValidationFailedException("Shipment", errors);
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Shipment? current)
    {
        await ValidateAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Shipment entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Parcel", out var parcel)) entity.Parcel = (Shipment.ParcelDocument)parcel!;
        if (values.TryGetValue("Stops", out var stops)) entity.Stops = (List<Shipment.StopDocument>?)stops;
    }

    /// <summary>The Shipment with this key; NotFoundException when there is none.</summary>
    private static async Task<Shipment> FindAsync(IUnitOfWork uow, string id) =>
        await uow.Shipments.FindByIdAsync(id) ?? throw new NotFoundException("Shipment", id);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(ShipmentChanges changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.Parcel is { IsPresent: true } parcel) values["Parcel"] = parcel.Value;
        if (changes.Stops is { IsPresent: true } stops) values["Stops"] = stops.Value;
        return values;
    }

    /// <summary>What a Shipment.ParcelDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckParcel(Shipment.ParcelDocument value, string path, List<FieldError> errors)
    {
        if (value.Contents is null) errors.Add(new FieldError(path + ".contents", "is required"));
        if (value.Size is not null) CheckParcelSize(value.Size, path + ".size", errors);
    }

    /// <summary>What a Shipment.ParcelDocument.SizeDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckParcelSize(Shipment.ParcelDocument.SizeDocument value, string path, List<FieldError> errors)
    {
    }

    /// <summary>What a Shipment.StopDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckStop(Shipment.StopDocument value, string path, List<FieldError> errors)
    {
    }

    /// <summary>Stores a new Shipment after checking it.</summary>
    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var values = new Dictionary<string, object?>();
        if (shipment.Parcel is not null) values["Parcel"] = shipment.Parcel;
        if (shipment.Stops is not null) values["Stops"] = shipment.Stops;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            return await uow.Shipments.InsertAsync(shipment);
        });
    }

    /// <summary>The Shipment with this key; NotFoundException when there is none.</summary>
    public async Task<Shipment> GetShipmentAsync(string id) => await FindAsync(uow, id);

    /// <summary>A page of shipments, by primary key.</summary>
    public async Task<Page<Shipment>> ListShipmentsAsync(int offset, int limit) => await uow.Shipments.ListAsync(offset, limit);

    /// <summary>Changes the given values of a Shipment.</summary>
    public async Task<Shipment> UpdateShipmentAsync(string id, ShipmentChanges changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return await uow.Shipments.UpdateAsync(current);
        });
    }

    /// <summary>Deletes a Shipment.</summary>
    public async Task DeleteShipmentAsync(string id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await uow.Shipments.DeleteAsync(current);
        });
    }

    /// <summary>Adds an item to stops.</summary>
    public async Task<Shipment> AddStopAsync(string id, Shipment.StopDocument stop)
    {
        var errors = new List<FieldError>();
        CheckStop(stop, "stops", errors);
        if (errors.Count > 0) throw new ValidationFailedException("Shipment", errors);
        return await this.uow.TransactionAsync(async uow =>
        {
            await FindAsync(uow, id);
            return await uow.Shipments.AddStopAsync(id, stop) ?? throw new NotFoundException("Shipment", id);
        });
    }

    /// <summary>Removes an item from stops, by its position.</summary>
    public async Task<Shipment> RemoveStopAsync(string id, int position)
    {
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if (current.Stops is null || position < 0 || position >= current.Stops.Count) throw new NotFoundException("Stop", position);
            return await uow.Shipments.RemoveStopAsync(id, position, current.Stops.Count) ?? throw new ConflictException("Shipment", "was changed by someone else since it was read", ["Stops"]);
        });
    }
}

